mapper.sql:
FROM system_user_company_department_scope s
INNER JOIN system_users u
    ON u.id = s.user_id
   AND u.tenant_id = s.tenant_id
   AND u.status = #{query.enabledStatus}
   AND u.deleted = FALSE
INNER JOIN system_company c
    ON c.id = s.company_id
   AND c.tenant_id = s.tenant_id
   AND c.status = #{query.enabledStatus}
   AND c.deleted = FALSE
INNER JOIN system_dept d
    ON d.id = s.department_id
   AND d.tenant_id = s.tenant_id
   AND d.code = s.department_code
   AND d.status = #{query.enabledStatus}
   AND d.deleted = FALSE
WHERE s.tenant_id = #{query.tenantId}
  AND s.company_id = #{query.companyId}
  AND s.department_id = #{query.departmentId}
  AND s.department_code = #{query.departmentCode}
  AND s.status = #{query.enabledStatus}
  AND s.deleted = FALSE
  AND s.effective_from <= #{query.currentTime}
  AND (s.effective_to IS NULL OR s.effective_to > #{query.currentTime})

  AND (u.username LIKE CONCAT('%', #{query.keyword}, '%')
       OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%'))
